def pages():
    P=[]
    # 31 principles + taiga
    P.append(page(4,K,"עקרונות וטייגה","Climate, biomes and the boreal forest",
    hero=sf("eco","<b>דוגמאות לאזורים אקולוגיים בעולם</b> על רקע תמונת Blue Marble של NASA: ירוק כהה: טייגה ויער גשם; ירוק בהיר: יער ממוזג; תכלת: טונדרה; צהוב: ערבות; כתום: מדבר; ורוד: ים-תיכוני; כחול: ביצות ואגמים. הנקודות הן אתרים מייצגים, לא גבולות.",""),
    cols=f'''
{sf("whittaker","<b>מפת הביומות לפי טמפרטורה ומשקעים</b> (סכמה מפושטת, בהשראת ויטאקר 1975). גבולות הביומות אינם חדים ותלויים גם בקרקע ובעונתיות.")}
<p>מערכת אקולוגית (<b>אקוסיסטמה</b>) היא קהילה של יצורים חיים וסביבתם הפיזית, שחוברים בזרימת אנרגיה ומחזור חומרים. בקנה מידה עולמי אפשר להגדיר <b>ביומות</b>, אזורים רחבים שחולקים אקלים וצורות חיים דומות. שני משתנים מסבירים רוב המפה: <b>הטמפרטורה השנתית הממוצעת</b> והמשקעים, כפי שרואים בדיאגרמת ויטאקר. אך התמונה מתעדנת בשל הקרקע, האש, העונתיות והחי.</p>
<h2>סוגי קרקע</h2>
<p>הקרקע אינה רק ״מצע״ אלא תוצר של אקלים וצמחייה. ביער מחטני קר נוצר <b>פודזול</b> חומצי ודל; ביער נשיר ממוזג <b>קרקע חומה</b> עשירה; בערבה מעשבים <b>מולי-סול</b> כהה ועמוק; במדבר <b>ארידי-סול</b> דל בחומר אורגני ולעיתים מלוח; ובטרופיים <b>אוקסי-סול</b> אדום, שטוף, עתיר ברזל ואלומיניום ודל בחומרי הזנה.</p>
<h2>הטייגה: יער הצפון הגדול</h2>
<p>הטייגה (היער הבוראלי) היא חגורה של יער מחטני סביב צפון הכדור בין כ-50 ל-70°N, בשטח שנאמד בכ-12 עד 17 מיליון קמ״ר, לפי ההגדרה. הטמפרטורה השנתית הממוצעת בין מינוס 5 לפלוס 5 מעלות, המשקעים 200 עד 750 מ״מ (לרוב כשלג), והחורף מגיע לכ-50 מעלות מתחת לאפס; באוימיאקון (סיביר) נמדדו כ-68 מעלות מתחת לאפס. הקרקע קפואה ברובה (פרמפרוסט) וחומצית.</p>
<p>העצים: אשוחית, אשוח, אורן ולרך. הלרך (<span class='lat'>Larix gmelinii</span>) משיר מחטים בחורף ולכן שורד בפרמפרוסט של סיביר. הצורה החרוטית שופכת שלג; המחטים העבות מצמצמות איבוד מים; והירוק הנצחי מאפשר לצמוח בראשית האביב בלי להשקיע בעלים חדשים.</p>
{box("data","הטייגה והאקלים","<p>קרקעות אזור הפרמפרוסט מכילות כ-1,300 מיליארד טונות פחמן, כמחצית מהפחמן הקרקעי בעולם (Hugelius ועמיתיו, 2014). עם ההתחממות, שבקווי הרוחב הגבוהים מהירה פי כמה מהממוצע, ההפשרה משחררת פחמן ומשתנה מערך השריפות: שריפות הענק של סיביר וקנדה בעשור האחרון הן סימן לכך.</p>")}
<p>בחי: אייל גדול (<span class='lat'>Alces alces</span>), לינקס, וולברין וזאב. <b>הארנבת הלבנה והלינקס</b> הן דוגמה קלאסית ליחסי טורף-נטרף עם מחזור של כ-10 שנים. ציפורים כמו הצלבן מתמחות בחרוטי אשוחית. השריפות הן חלק מהמחזור: חלק מהאורנים פתוחים רק בחום.</p>
''',toc="עקרונות וטייגה"))
    # 32 temperate
    P.append(page(4,K,"יערות ממוזגים ויערות גשם ממוזגים","Temperate forests and temperate rainforests",
    hero=sf("fl_tmp","<b>מבנה יער גשם ממוזג</b> (סכמטי). הגובה בקירוב; גזע אם (nurse log) הוא מצע להתחדשות.","w1")+sf("hb_trees","<b>העצים הגבוהים בעולם</b> לפי מדידות שדה (מ׳). שלושה מהם גדלים ביער גשם ממוזג.","w1"),
    cols=f'''
<h2>יער נשיר ממוזג</h2>
<p>במזרח צפון אמריקה, במערב ובמרכז אירופה ובמזרח אסיה צומח <b>יער נשיר ממוזג</b>: אלון, אשור, אדר, ליבנה. האקלים בעל ארבע עונות, משקעים 750 עד 1,500 מ״מ בשנה, חורף קר וקיץ חם. העצים משירים עלים בסתיו כדי להימנע מאיבוד מים ומנזק קפיאה, והקרקע <b>חומה, עשירה</b> ברקבובית. בסתיו הכלורופיל מתפרק וחושף פיגמנטים צהובים וכתומים (קרוטנואידים), ובמינים מסוימים נוצרים פיגמנטים אדומים (אנתוציאנינים). באביב צמחים יערניים קצרים (״אפמרים״) פורחים לפני שהחופה נסגרת. החי: צבי, דוב שחור, סנאים, ציפורים נודדות.</p>
<h2>יער גשם ממוזג</h2>
<p>במקומות מעטים בעולם הגשם והלחות של היער הטרופי נפגשים עם אקלים ממוזג: חוף הפסיפי של צפון אמריקה (מצפון קליפורניה עד אלסקה, באורך כ-4,000 ק״מ), צ׳ילה הדרומית (יער ולדיביה), ניו זילנד, טסמניה, יפן, נורווגיה והאיים הבריטיים, והקולכיס בקווקז. הקריטריונים: משקעים גבוהים (בדרך כלל מעל 1,400 מ״מ בשנה) וטמפרטורות מתונות בלי חורף חמור. בפסיפי: אשוחית סיטקה, הֶמלוק מערבי, ארז אדום ודגלס, וקרוב לחוף קליפורניה: <b>סקויה</b> (<span class='lat'>Sequoia sempervirens</span>) עד כ-116 מ׳ (הייפריון, 115.9 מ׳). <b>הטונגס</b> באלסקה (כ-6.8 מיליון הקטר) הוא היער הלאומי הגדול בארצות הברית.</p>
{box("journey","מסע: יער הגשם של צפון-מערב ארצות הברית (כ-2,500 ק״מ צפונה)","<p><b>קליפורניה: יער הסקויות.</b> ערפל קיץ מהאוקיינוס הקר מספק עד כ-30 עד 40 אחוז מהמים לעצים (מחקרי דוסון), ולכן הסקויות צומחות בחוף. <b>אורגון:</b> ההֶמלוק והדגלס משתלטים; עצי האשוחית מתקרבים לים. <b>אולימפיק (וושינגטון):</b> 3,500 עד 4,300 מ״מ בשנה ביער הו; גזעים עמוסי אזוב. <b>קולומביה הבריטית:</b> ביער הגשם הגדול של הדוב, דוב ״הרוח״ הלבן (קרמוד). <b>אלסקה:</b> ארז צהוב והמלוק, וסלמון: מדי שנה הדגים חוזרים אל הנחלים, הדובים גוררים אותם ליער, ומחנקן הים שהם מותירים (חלק ניכר מהחנקן בעצים לצד נחלים) מוזן היער. עם כל קילומטר צפונה יורדת הטמפרטורה והעצים נמוכים יותר, אך הלחות נשארת.</p>")}
<h2>למה היער הממוזג צפוף בביומסה?</h2>
<p>היער הגשום הממוזג מכיל כמות עצומה של פחמן: האטמוספרה הקרירה והלחה מאטה את הפירוק, והעצים הגדולים חיים מאות שנים. גזע נופל נשאר על האדמה במשך עשרות או מאות שנים כמגדל של חיים.</p>
''',toc="יערות ממוזגים ויערות גשם ממוזגים"))
    # 33 tropical
    P.append(page(4,K,"יער הגשם הטרופי ומבט משווה","Tropical rainforests — and how they differ from temperate ones",
    hero="",
    cols=f'''
{sf("fl_trop","<b>מבנה יער גשם טרופי</b> (סכמטי). הגבהים בקירוב. אל הקרקעית מגיע כ-2 אחוז מהאור בלבד.")}
<p>היער הטרופי נמצא ברצועה של כ-10° מצפון ומדרום לקו המשווה: אמזונס, אגן קונגו וארכיפלג דרום-מזרח אסיה. הטמפרטורה כמעט קבועה (25 עד 27°C בממוצע), ומשקעים 2,000 עד 4,000 מ״מ בשנה ללא עונת יובש חמורה. למרות זאת הקרקע <b>דלה</b>: העוצמה של הגשם שוטפת מינרלים, ולכן רוב הרכיבים התזונתיים נמצאים בביומסה החיה; פטריות מיקוריזה וחיידקים ממחזרים עלים נושרים תוך שבועות.</p>
<h2>מבנה ומגוון</h2>
<p>היער מחולק לשכבות: <b>שכבה בולטת</b> (עצים בודדים עד כ-60 מ׳), <b>חופה</b> רציפה (25 עד 35 מ׳), <b>תת-חופה</b> וקרקעית חשוכה. רוב החיים נמצאים בחופה: צמחי אפיפיט (סחלבים, ברומליות), לאנות, קופים וציפורים. בחלקת אמזונס אחת של הקטר יש מאות מינים של עצים. הערכה מקובלת (ter Steege ועמיתיו, 2013): כ-390 מיליארד עצים ו-16,000 מיני עצים בבסיס האמזונס, אך מחצית מהעצים שייכים ל-227 מינים בלבד (״היפר-דומיננטיות״).</p>
<p>יערות הגשם הטרופיים מכסים כ-6 עד 7 אחוז מהיבשה ומכילים, לפי הערכות נפוצות, יותר ממחצית מהמינים היבשתיים. אגן האמזונס (כ-6.7 מיליון קמ״ר, כ-60 אחוז בברזיל) מספק כ-20 אחוז מזרימת הנהרות בעולם. היער גם ״מייצר״ את הגשם שלו: כמחצית מהמשקעים מוחזרת באידוי מהצמחים (<b>״נהרות מעופפים״</b>).</p>
{box("compare","יער גשם ממוזג לעומת טרופי",table([["טמפרטורה","5 עד 15°C, עונתית","25 עד 27°C, יציבה"],["משקעים","1,400 עד 4,000+ מ״מ","2,000 עד 4,000 מ״מ"],["מינים של עצים","3 עד 10 דומיננטיים","100 עד 300 להקטר"],["גובה העצים","60 עד 115 מ׳","40 עד 60 מ׳ (שיא ~100)"],["קרקע","רקבובית עבה, חומצית","דלה; נוטריינטים בביומסה"],["פירוק","איטי (שנים)","מהיר (שבועות)"],["צמחים על עצים","אזוב, שרכים, חזזיות","סחלבים, ברומליות"],["הפרעה","סערות, שריפה נדירה","נפילת עצים, שטפונות"]],["","ממוזג","טרופי"]))}
<h2>איומים</h2>
<p>כריתה לחקלאות וכריית זהב מצמצמות את היער. מחקר של לאבג׳וי ונובר (2018) הציע כי אם יאבד 20 עד 25 אחוז מהאמזונס, עלולה המערכת לעבור ל״סוואנה״ עקב קריסת מחזור המים. בחלקים מהאמזונס הדרומי כבר הפך היער למקור פחמן נטו (נתוני ניטור לווייני ושדה).</p>
''',toc="יער הגשם הטרופי והשוואה"))
    # 34 tundra
    P.append(page(4,K,"טונדרה: ארקטית ואלפינית","Arctic and alpine tundra",
    hero=sf("lat_lines","<b>קו העצים וקו השלג בקווי רוחב שונים</b> (ערכים משוערים, לפי סקירות קרנר ואחרות). בטרופיים הקווים גבוהים מאוד; לכיוון הקטב הם יורדים אל פני הים.","w1")+sf("vb_tree","<b>גובה קו העצים</b> באזורים נבחרים (מ׳, משוער).","w1"),
    cols=f'''
<p>טונדרה היא אזור ללא עצים בגלל קור. בשני סוגים: <b>ארקטית</b> (מעל קו העצים הצפוני) ו<b>אלפינית</b> (מעל קו העצים בהרים). הטונדרה הארקטית מכסה כ-8 אחוז מהיבשה בקירוב. הטמפרטורה השנתית ממינוס 12 עד מינוס 6 מעלות, הקיץ 3 עד 12°C, ומשקעים 150 עד 250 מ״מ בלבד: כמו מדבר, אך הקרקע רוויה כי הקור מונע אידוי וניקוז.</p>
<h2>פרמפרוסט ורצועה פעילה</h2>
<p>קרקע שנשארת קפואה שנתיים ויותר היא <b>פרמפרוסט</b>. בקיץ נמסה רק <b>השכבה הפעילה</b> (עשרות ס״מ עד מטר). החלפה בין קפיאה להפשרה יוצרת <b>קרקע מצולעת</b> (patterned ground) ו״גבשושיות קרח״ (pingo). הקרקע הקפואה מונעת ניקוז ויוצרת אגמים וביצות עונתיים; הפשרה גורמת לקריסת פני השטח.</p>
<h2>צמחים וחיות</h2>
<p>צמחייה נמוכה: טחבים, חזזיות, שיחי ערבה ננסיים, גומא וצמחי כרית. הצמחים צומחים לאט (שיח עשוי להיות בן מאה שנה ובקוטר של מטרים בודדים). מן החי: לֶמינג (עם מחזורי שפע של 3 עד 4 שנים), שועל קוטב, ינשוף שלג, קריבו, שור מושק ודוב קוטב. <b>נדידתה</b> של שחפית הקוטב (<span class='lat'>Sterna paradisaea</span>) כ-70,000 ק״מ בשנה, מהארקטי לאנטארקטיקה וחזרה.</p>
{box("compare","טונדרה אלפינית לעומת ארקטית",table([["יום ולילה","מחזור 24 שעות","קיץ בלי לילה, חורף בלי יום"],["קרינה","חזקה (גובה)","נמוכה"],["קרקע","ניקוז טוב","פרמפרוסט, רוויה"],["אוויר","דליל, פחות חמצן","צפוף"],["רוח","חזקה","חזקה"],["בעלי חיים","פיקה, מרמוטה","לֶמינג, קריבו"]],["","אלפינית","ארקטית"]))}
{box("nature","מדוע קו העצים משתנה בין רכסי הרים?","<p>עצים זקוקים לעונה שבה טמפרטורת הקרקע עוברת כ-6°C (קרנר). ככל שהקו עולה לכיוון קו המשווה, כך מתרוממת הגבול. אבל מאסת ההר, הרוח, השלג והקרקע משנים: בהרים גדולים (הימלאיה) הקרקע חמה יותר, ולכן הקו גבוה יותר מבהרים קטנים באותו רוחב (״אפקט מסת ההר״).</p>")}
<h2>טונדרה בשינוי</h2>
<p>הארקטי מתחמם פי ארבעה בקירוב מהממוצע העולמי מאז 1979 (Rantanen ועמיתיו, 2022). שיחים גבוהים מתפשטים (<b>״התשיחה״</b>), הפרמפרוסט נמס, ועונת הצמיחה מתארכת. בהרים קווי העצים עולים מטרים בודדים בעשור, וצמחים אלפיים מתחרים עם מינים מהגבהים הנמוכים.</p>
''',toc="טונדרה: ארקטית ואלפינית"))
    return P
